+++ b/test_unicode_errors.go
@@ -0,0 +1,23 @@
+package main
+
+import (
+    "fmt"
+    "github.com/bytedance/sonic"
+)
+
+func main() {
+    // Test data with invalid UTF-8 escape sequence
+    invalidData := []byte(`"\uDD1E"`)
+
+    // Test with UseUnicodeErrors disabled (default)
+    cfg1 := sonic.Config{}.Froze()
+    var result1 string
+    err1 := cfg1.Unmarshal(invalidData, &result1)
+    fmt.Printf("Without UseUnicodeErrors: err=%v\n", err1)
+
+    // Test with UseUnicodeErrors enabled
+    cfg2 := sonic.Config{UseUnicodeErrors: true}.Froze()
+    var result2 string
+    err2 := cfg2.Unmarshal(invalidData, &result2)
+    fmt.Printf("With UseUnicodeErrors: err=%v\n", err2)
+}

